module tb;
    reg in;
    wire out;

    TopModule dut (
        .in(in),
        .out(out)
    );

    initial begin
        in = 0;
        #10;
        if (out !== 1'b1) begin
            $display("SELFTEST FAIL: in=0, expected out=1, got %b", out);
            $finish;
        end

        in = 1;
        #10;
        if (out !== 1'b0) begin
            $display("SELFTEST FAIL: in=1, expected out=0, got %b", out);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
